#!/usr/bin/env bash
# Plants the "Test Doubles with dependency_overrides" challenge.
# Idempotent — re-running overwrites source files but does not delete .venv.
set -euo pipefail

WORK="$HOME/.kube-dojo-work/05-test-doubles"
mkdir -p "$WORK/tests"

# ── main.py — complete app, learner must NOT edit ───────────────────────────
cat > "$WORK/main.py" << 'PYEOF'
# main.py — complete app. Do NOT edit this file.
from fastapi import FastAPI, Depends, HTTPException
from pydantic import BaseModel
from typing import Protocol, runtime_checkable


@runtime_checkable
class NotificationService(Protocol):
    def send_welcome(self, username: str) -> None: ...
    def send_goodbye(self, username: str) -> None: ...


class EmailNotifier:
    """Real notifier — raises to prevent accidental use in tests."""
    def send_welcome(self, username: str) -> None:
        raise RuntimeError("real EmailNotifier called in tests — use a test double")

    def send_goodbye(self, username: str) -> None:
        raise RuntimeError("real EmailNotifier called in tests — use a test double")


def get_notifier() -> NotificationService:
    return EmailNotifier()


app = FastAPI()
_users: list[str] = []


class UserCreate(BaseModel):
    username: str


@app.post("/users", status_code=201)
def create_user(
    user: UserCreate,
    notifier: NotificationService = Depends(get_notifier),
):
    if user.username in _users:
        raise HTTPException(status_code=409, detail="already exists")
    _users.append(user.username)
    notifier.send_welcome(user.username)
    return {"username": user.username}


@app.delete("/users/{username}", status_code=204)
def delete_user(
    username: str,
    notifier: NotificationService = Depends(get_notifier),
):
    if username not in _users:
        raise HTTPException(status_code=404, detail="not found")
    _users.remove(username)
    notifier.send_goodbye(username)
PYEOF

# ── tests/__init__.py ────────────────────────────────────────────────────────
cat > "$WORK/tests/__init__.py" << 'PYEOF'
PYEOF

